              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={sparkData}>
                  <Line
                    type="monotone"
                    dataKey="value"
                    stroke={indicator.color}
                    strokeWidth={1.5}
                    dot={false}
                    connectNulls={false}
                  />
